import{_ as t,o,c as d,ak as a}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse('{"title":"Test search","description":"The search box of the Tests tabs: words, qualifiers such as file: and describe:, exclusions and wildcards, and the keys that complete them.","frontmatter":{"title":"Test search","description":"The search box of the Tests tabs: words, qualifiers such as file: and describe:, exclusions and wildcards, and the keys that complete them.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/test-search.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/test-search.html"}],["meta",{"property":"og:title","content":"Test search | Piwi Dashboard"}],["meta",{"property":"og:description","content":"The search box of the Tests tabs: words, qualifiers such as file: and describe:, exclusions and wildcards, and the keys that complete them."}]]},"headers":[],"relativePath":"reference/test-search.md","filePath":"reference/test-search.md","lastUpdated":1790871667000}'),r={name:"reference/test-search.md"};function s(c,e,i,h,n,l){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="test-search" tabindex="-1">Test search <a class="header-anchor" href="#test-search" aria-label="Permalink to &quot;Test search&quot;">​</a></h1><p>A run&#39;s <strong>Tests</strong> tab and a project&#39;s <strong>Tests</strong> tab share one search box and one language: words that look in every text of a test, and qualifiers in the style of GitHub search that look in one field, such as <code>file:cart.spec.ts</code> or <code>describe:&quot;Guest checkout&quot;</code>. The box lists the qualifiers when it is empty and the values each one can take as you type, and the list marks what matched. <code>Ctrl</code> + <code>F</code> (<code>⌘</code> + <code>F</code> on macOS) jumps to the box; pressed again there, it opens the browser&#39;s own find.</p><h2 id="words-and-phrases" tabindex="-1">Words and phrases <a class="header-anchor" href="#words-and-phrases" aria-label="Permalink to &quot;Words and phrases&quot;">​</a></h2><p>A word matches the test title, its describe blocks or its file path, and, on a run&#39;s Tests tab, the error text too. Every word must match, in any of them: <code>login timeout</code> finds the tests that mention both. Quotes keep spaces inside one term: <code>&quot;guest checkout&quot;</code>.</p><h2 id="qualifiers" tabindex="-1">Qualifiers <a class="header-anchor" href="#qualifiers" aria-label="Permalink to &quot;Qualifiers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Qualifier</th><th>Also written</th><th>Matches</th><th>Tests tab</th></tr></thead><tbody><tr><td><code>file:</code></td><td><code>path:</code></td><td>The spec file path</td><td>Run and project</td></tr><tr><td><code>describe:</code></td><td><code>suite:</code></td><td>A describe block</td><td>Run and project</td></tr><tr><td><code>title:</code></td><td><code>test:</code>, <code>name:</code></td><td>The test title</td><td>Run and project</td></tr><tr><td><code>tag:</code></td><td></td><td>A tag, with or without its <code>@</code></td><td>Run and project</td></tr><tr><td><code>browser:</code></td><td><code>project:</code></td><td>The Playwright project the execution ran in</td><td>Run</td></tr><tr><td><code>error:</code></td><td></td><td>The error text</td><td>Run</td></tr><tr><td><code>lock:</code></td><td></td><td>A <a href="/reference/test-metadata.html#test-locks">lock</a> the test declares</td><td>Run and project</td></tr><tr><td><code>owner:</code></td><td></td><td>The <code>piwi:owner</code> <a href="/reference/test-metadata.html#ownership-metadata-piwi-annotations">annotation</a></td><td>Run and project</td></tr><tr><td><code>priority:</code></td><td></td><td>The <code>piwi:priority</code> annotation</td><td>Run and project</td></tr><tr><td><code>feature:</code></td><td></td><td>The <code>piwi:feature</code> annotation</td><td>Run and project</td></tr></tbody></table><p>How the terms combine:</p><ul><li><code>file:</code>, <code>describe:</code>, <code>title:</code> and <code>error:</code> match anywhere in the text, and <code>*</code> stands for any characters: <code>file:checkout/*.spec.ts</code>. The other qualifiers match a whole value.</li><li>Case never matters.</li><li>Every term must match. The exception is a qualifier of which a test has only one value (<code>file:</code>, <code>browser:</code>, <code>owner:</code>, <code>priority:</code>, <code>feature:</code>): repeated, it matches any of the values, so <code>file:cart file:checkout</code> lists both files.</li><li>A leading <code>-</code> excludes: <code>-tag:slow</code>, <code>-describe:legacy</code>, <code>-flaky</code>.</li><li>A qualifier the tab does not have, such as <code>error:</code> on a project, is read as a word.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Search</th><th>Finds</th></tr></thead><tbody><tr><td><code>file:cart</code></td><td>The tests of every file whose path contains <code>cart</code></td></tr><tr><td><code>describe:&quot;Guest checkout&quot; -tag:slow</code></td><td>The tests inside a <em>Guest checkout</em> block that are not tagged <code>@slow</code></td></tr><tr><td><code>timeout browser:webkit</code></td><td>On a run: the WebKit executions whose title, blocks, path or error mention <code>timeout</code></td></tr><tr><td><code>owner:@team/payments priority:critical</code></td><td>The critical tests the payments team owns</td></tr><tr><td><code>title:&quot;refund*email&quot;</code></td><td>The tests whose title has <code>refund</code>, then <code>email</code> further on</td></tr></tbody></table><h2 id="completion" tabindex="-1">Completion <a class="header-anchor" href="#completion" aria-label="Permalink to &quot;Completion&quot;">​</a></h2><p>The suggestions follow the term under the caret. An empty term lists the qualifiers; a qualifier lists the values it can take, with how many tests carry each; a word lists the qualifiers it starts and the values that contain it. On a run the values come from its executions; on a project, from every test case in the chosen age window.</p><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><code>↓</code> / <code>↑</code></td><td>Move through the suggestions</td></tr><tr><td><code>Enter</code> / <code>Tab</code></td><td>Take the highlighted suggestion</td></tr><tr><td><code>Esc</code></td><td>Close the suggestions</td></tr></tbody></table><p>While you type a qualifier&#39;s value, the closest match is highlighted, so <code>Enter</code> completes it. A plain word is never replaced by a qualifier unless you move to one first.</p><h2 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to &quot;Order&quot;">​</a></h2><p>Both tabs read in the order of the suite unless you pick another sort. A run&#39;s Tests tab opens in <strong>Run order</strong>, when each test first started (a retried test counts from its first attempt), and in <strong>File order</strong> when grouped by file: file path, then the line and column the test is declared at, the order <code>playwright test --list</code> prints. A project&#39;s Tests tab opens in File order. In the <em>File + Describe</em> grouping, a describe block keeps its place in the file among the tests around it. Outside that grouping, a test&#39;s describe blocks are named before its title: <code>Checkout › pays by card</code>.</p><p>The test catalog&#39;s <code>q</code> API parameter and the <code>query</code> argument of the MCP <code>get_project_test_catalog</code> tool take the same language (<a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a>, <a href="/reference/mcp-tools.html">MCP tools</a>).</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/ui-overview.html">UI overview</a>: the run and project Tests tabs</li><li><a href="/reference/test-metadata.html">Test metadata</a>: the tags, locks and <code>piwi:</code> annotations the qualifiers read</li><li><a href="/reference/keyboard-shortcuts.html">Keyboard shortcuts</a>: every key the dashboard registers</li></ul>',19)])])}const f=t(r,[["render",s]]);export{p as __pageData,f as default};
